def choose_move(observation):
    g = observation if isinstance(observation, dict) else {}
    w = g.get("grid_width", 0)
    h = g.get("grid_height", 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return int(v[0]), int(v[1])
        if isinstance(v, dict) and "x" in v and "y" in v:
            return int(v["x"]), int(v["y"])
        return None

    def step(a, b):
        return (-1 if b[0] < a[0] else 1 if b[0] > a[0] else 0,
                -1 if b[1] < a[1] else 1 if b[1] > a[1] else 0)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    me = pos(g.get("self_position"))
    opp = pos(g.get("opponent_position"))
    if me is None:
        return [0, 0]

    obs = set()
    for it in g.get("obstacles") or []:
        p = pos(it)
        if p is not None:
            obs.add(p)

    res = []
    for it in g.get("resources") or []:
        p = pos(it)
        if p is not None:
