    if res:
        target = min(res, key=lambda p: (dist(me, p), abs(p[0] - (w - 1) / 2) + abs(p[1] - (h - 1) / 2)))
    elif opp is not None:
        target = ((0 if opp[0] >= w / 2 else w - 1), (0 if opp[1] >= h / 2 else h - 1))
    else:
        target = ((w - 1) // 2, (h - 1) // 2)

    dx, dy = step(me, target)
    cand = [(dx, dy)]
    if dx != 0:
        cand.append((dx, 0))
    if dy != 0:
        cand.append((0, dy))
    cand += [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

